// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount);
        bool ok;
        try attacker.go(amount) { ok = true; } catch { ok = false; }
        // Rule: a re-entrant second withdrawAll (fired from the payout of the first)
        // must be a no-op because the caller's credit was zeroed: the whole
        // transaction always succeeds. The mutant leaves credit outstanding,
        // so the re-entry underflows `balance` and reverts.
        assertTrue(ok);
    }
}

contract Attacker {
    ReentrancyDAO c;
    bool private entered;
    constructor(ReentrancyDAO _c) { c = _c; }
    function go(uint256 amt) external payable {
        c.deposit{value: amt}();
        c.withdrawAll();
    }
    receive() external payable {
        if (!entered) {
            entered = true;
            c.withdrawAll();
        }
    }
}
